window.PROTOTYPE_FAM=FAM;
window.PROTOTYPE_ANNOTATIONS=ANNO;
window.getPrototypeAnnotations=function(pageKey){
  const fam=(window.PROTOTYPE_PAGE_FAMILIES||{})[pageKey];
  if(!fam) return [];
  if(window.PROTOTYPE_ANNOTATIONS&&window.PROTOTYPE_ANNOTATIONS[fam]) return window.PROTOTYPE_ANNOTATIONS[fam];
  const f=window.PROTOTYPE_FAM&&window.PROTOTYPE_FAM[fam];
  const out=[];
  if(f&&f.src) out.push(['字段来源',f.src]);
  if(f&&f.mark) out.push(['决策 / 备注',f.mark]);
  return out;
};
